import{_ as i,o as a,c as t,a5 as s}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Verification","description":"","frontmatter":{},"headers":[],"relativePath":"feature/caption-text-moderation/test.md","filePath":"feature/caption-text-moderation/test.md"}'),r={name:"feature/caption-text-moderation/test.md"};function n(o,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h1><ul><li>Clean English and Vietnamese fixture =&gt; PASSED only when supported classification exists.</li><li>Harmful class severity 3 =&gt; BLOCKED; severity 1/2 =&gt; WARNING; promotion/phone number alone =&gt; PASSED.</li><li>Profanity/PII filters =&gt; WARNING; unknown, empty, unsupported, partial, invalid score or provider failure =&gt; NOT_CHECKED unless a verified blocking issue is already found.</li><li>Long captions, emoji and segment boundaries: every character covered; segment &lt;=1,024 UTF-16 units, overlap retained; no silent truncation.</li><li>Missing key makes no HTTP call. Wrong key, 429, timeout, invalid JSON =&gt; NOT_CHECKED; no credential/caption in logs/errors.</li><li>Internal route rejects absent/bad X-Internal-Key. Workspace endpoint enforces existing access checks.</li><li>Generation/refine/adapt results carry moderation without using Deploy LLM key or altering generation billing.</li><li>Manual check: pending, success, unavailable; editing clears verdict; older response ignored. Blocked generated caption cannot Apply; edited caption cannot use prior verdict.</li><li>Change vi/en: all labels translated; light/dark contrast, narrow screen wrapping and keyboard activation.</li><li>Live probe only on user-approved endpoint with benign synthetic text, output redacted. Never claim live success from mocks.</li></ul><h2 id="results-2026-10-28" tabindex="-1">Results (2026-10-28) <a class="header-anchor" href="#results-2026-10-28" aria-label="Permalink to &quot;Results (2026-10-28)&quot;">​</a></h2><ul><li>Python: 57 passed across moderation, caption generation and provider fallback tests; provider calls mocked, live moderation key disabled.</li><li>Java: AiCaptionServiceTest 10 passed; CaptionModerationTest 4 passed.</li><li>Playwright: 6 focused tests passed; 5 moderation tests rerun after correct theme setup, passed. Dark/light moderation screenshots visually inspected at mobile width.</li><li>Frontend TypeScript/build and focused ESLint passed (final lint/typecheck rerun recorded in chat). Existing build chunk-size warning remains.</li><li>Approved live V3 request to <a href="https://api.thehive.ai/api/v3/hive/text-moderation" target="_blank" rel="noreferrer">https://api.thehive.ai/api/v3/hive/text-moderation</a> returned 401, message Invalid or expired token. Successful live moderation remains blocked by credential validity. No credential values saved in artifacts.</li></ul><h2 id="typing-and-immediate-publish-tests" tabindex="-1">Typing and immediate publish tests <a class="header-anchor" href="#typing-and-immediate-publish-tests" aria-label="Permalink to &quot;Typing and immediate publish tests&quot;">​</a></h2><ul><li>No request at 2,999ms; exactly one at 3,000ms. Typing at 2s resets the delay.</li><li>Clicking Publish Now at 2s sends moderation immediately, not publish; only after a successful result may publish be called.</li><li>Clicking during an active check joins it; clicking repeatedly does not duplicate publish.</li><li>BLOCKED, NOT_CHECKED, malformed response or HTTP failure makes zero publish requests and preserves text.</li><li>Editing while a check is active aborts/ignores old result; it must never authorize the edited text.</li><li>Valid exact-text result is reused; changing caption, hashtags, or workspace invalidates it.</li><li>Empty text never checks. Unmount clears timer and aborts outstanding request.</li></ul><h3 id="typing-publish-verification-results" tabindex="-1">Typing/publish verification results <a class="header-anchor" href="#typing-publish-verification-results" aria-label="Permalink to &quot;Typing/publish verification results&quot;">​</a></h3><ul><li>8 Vitest unit tests passed: exact debounce/reset, in-flight deduplication, snapshot reuse/invalidation, empty/oversized text, abort/stale responses and disposal.</li><li>11 Playwright tests passed with mocked moderation/publish: debounce; early/in-flight/cached request order; blocked/unchecked/HTTP-error/malformed response; edit-during-publish-check race; mobile light/dark.</li><li>npm run build passed; focused ESLint passed; git diff --check passed. Light/dark screenshots visually inspected. Existing bundle size warning remains.</li><li>No new live Hive request or real publish performed during these checks.</li></ul><h2 id="failure-diagnostics-regression" tabindex="-1">Failure diagnostics regression <a class="header-anchor" href="#failure-diagnostics-regression" aria-label="Permalink to &quot;Failure diagnostics regression&quot;">​</a></h2><ul><li>Mock 401/403/429/500, timeout, connection failure, malformed JSON and missing key; assert NOT_CHECKED with the corresponding fixed issue code.</li><li>Assert logs contain reason and status when available, but exclude key, caption, upstream response and exception text.</li><li>Existing dedicated-key, segment aggregation and provider parsing tests continue passing. Locale keys must remain parallel; existing shared UI/theme layout unchanged.</li></ul><p>Failure diagnostics results: 30 provider/service tests passed (2 endpoint/generation tests excluded because the earlier full run stalled during endpoint imports). Eight added regression cases cover specific reason codes and sensitive-data redaction. Vietnamese/English moderation issue key sets match (28 each). No live provider verification or credential changes performed. UI component styles/layout unchanged; visual verification not rerun for text-only changes. Editor moderation coordinator: 8 Vitest tests passed (debounce/reset, reuse, deduplication, stale requests and failure handling).</p><h2 id="entity-and-language-coverage-regression" tabindex="-1">Entity and language coverage regression <a class="header-anchor" href="#entity-and-language-coverage-regression" aria-label="Permalink to &quot;Entity and language coverage regression&quot;">​</a></h2><ul><li>Benign fully classified text with athlete/celebrity/politician/religious_figure/likeness match =&gt; PASSED, no custom warning.</li><li>Vietnamese-shaped partial classification (hate=0, violence=-1) with athlete =&gt; NOT_CHECKED, unsupported_violence only. Fixed diagnostics log category names but no input text. This is a synthesized provider fixture, not a captured live response.</li><li>PII types in all supported containers warn; profanity/custom still warn and IWF still blocks. Malformed filter arrays cannot pass.</li><li>Parallel vi/en unsupported-category keys; no unsupported group becomes PASSED. Existing Publish Now gate and coordinator regressions pass.</li></ul><p>Entity/coverage results: 48 provider tests passed, 2 endpoint/generation tests excluded as previously documented. Editor coordinator: 8 passed. vi/en keys match; git diff --check passed. Regression fixtures are synthetic; no authenticated live request or real publish performed. Existing UI components/theme tokens are reused. Frontend TypeScript project build (tsc -b): passed.</p><h2 id="generic-partial-response-diagnosis" tabindex="-1">Generic partial response diagnosis <a class="header-anchor" href="#generic-partial-response-diagnosis" aria-label="Permalink to &quot;Generic partial response diagnosis&quot;">​</a></h2><p>Assert missing classes, unsupported language, invalid filter containers and unrecognized classes produce distinct safe diagnostics; captions and credentials never appear.</p><p>Generic incomplete diagnostics: 5 specific redaction tests and 53 provider/service tests passed; 2 endpoint/generation tests excluded. Live diagnosis awaits a fresh editor request after reload; existing 20:15/20:16 access logs alone cannot distinguish partial-response causes.</p><h2 id="class-entry-contract-correction" tabindex="-1">Class entry contract correction <a class="header-anchor" href="#class-entry-contract-correction" aria-label="Permalink to &quot;Class entry contract correction&quot;">​</a></h2><p>Mock actual HTTP payload with class/score: 0=&gt;PASSED, 1/2=&gt;WARNING, 3=&gt;BLOCKED, -1=&gt;NOT_CHECKED. Conflicting/mixed aliases cannot pass. Keep previous alias/parser/filter/transport tests. Live payload shape is not yet captured; verify original symptom in editor separately.</p><p>Class-entry correction verification: regression initially reproduced no_supported_harmful_class on class/score payload. After correction, 63 provider/service tests passed, 2 endpoint/generation tests excluded as previously documented. Default fixtures now use class/score, with explicit alias compatibility/conflict tests. No live credential transmission; user reported not yet rechecking editor. Original live symptom verification remains pending.</p><h2 id="live-schema-diagnosis" tabindex="-1">Live schema diagnosis <a class="header-anchor" href="#live-schema-diagnosis" aria-label="Permalink to &quot;Live schema diagnosis&quot;">​</a></h2><p>Live schema logging must not contain caption, secret, arbitrary keys or values. Actual schema regression and live editor verification are required before claiming compatibility.</p><h2 id="observed-v3-class-value-schema" tabindex="-1">Observed V3 class/value schema <a class="header-anchor" href="#observed-v3-class-value-schema" aria-label="Permalink to &quot;Observed V3 class/value schema&quot;">​</a></h2><p>Observed class/value shape: 0 clean, 1/2 warning, 3 block, -1 unchecked. Red regression reproduced original no_supported_harmful_class with this shape. Other alias and error regressions must pass.</p><p>Observed live shape at 20:28:58: class:str,value:int, other_fields=0. Corrected parser: 67 provider/service tests passed (2 endpoint/generation tests excluded). Live-shaped regression went red before fix and green afterward. Temporary schema logging removed. Fresh live editor verification pending.</p><p>Runtime verification remains pending: runner log last records WatchFiles Reloading at 20:29:32, without a subsequent startup or request during verification. User must retry after startup; do not claim live completion from 67 passing offline tests.</p><h2 id="partial-coverage-policy-reloop-reference" tabindex="-1">Partial coverage policy (ReLoop reference) <a class="header-anchor" href="#partial-coverage-policy-reloop-reference" aria-label="Permalink to &quot;Partial coverage policy (ReLoop reference)&quot;">​</a></h2><p>Mixed supported0/unsupported-1 =&gt; WARNING with named coverage issues; mixed supported3/unsupported-1 =&gt; BLOCKED. All unsupported =&gt; NOT_CHECKED. Unsupported+malformed/timeout segment remains NOT_CHECKED. No mock safe fallback. vi/en keys match, WARNING publishes through existing gate, BLOCKED/NOT_CHECKED do not.</p><p>Partial-coverage policy verification: 72 provider/service tests and 8 editor coordinator tests passed; 2 endpoint/generation tests excluded as previously documented. TypeScript and focused ESLint passed. Locale key parity and diff checks passed. Browser partial-warning publish test pending. ReLoop mock-safe fallback and confidence thresholds were deliberately excluded. Browser test was stopped after remaining at dev-server startup without reaching the test; no browser pass claimed. Real publishing was not performed.</p><h2 id="user-requested-unsupported-as-safe-policy" tabindex="-1">User requested unsupported-as-safe policy <a class="header-anchor" href="#user-requested-unsupported-as-safe-policy" aria-label="Permalink to &quot;User requested unsupported-as-safe policy&quot;">​</a></h2><p>Unsupported-only valid classification =&gt; PASSED. Actual harmful score1/3 =&gt; WARNING/BLOCKED with score. HTTP/malformed fails remain NOT_CHECKED. Rule matches without numerical severity have null score.</p>',31)])])}const g=i(r,[["render",n]]);export{h as __pageData,g as default};
